/* ---------------------------------------------------------------------------
 * Convierte la respuesta de values:batchGet en objetos por hoja.
 * batchGet devuelve matrices crudas: la primera fila son los encabezados.
 * ------------------------------------------------------------------------ */

const TABS = ["comunas", "sucursales", "equipos", "industrias", "parametros"];

/** Matriz [[hdr],[fila],…] -> [{hdr: valor}] , saltando filas vacías. */
function aObjetos(values) {
  if (!Array.isArray(values) || values.length < 2) return [];
  const hdr = (values[0] || []).map(h => String(h === null || h === undefined ? '' : h).trim());
  const out = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i] || [];
    // La hoja trae un bloque de NOTAS al final: se corta ahí.
    if (String(row[0] || '').trim().toUpperCase() === 'NOTAS') break;
    if (String(row[0] || '').trim().startsWith('•')) continue;
    if (!row.some(c => c !== '' && c !== null && c !== undefined)) continue;
    const o = {};
    hdr.forEach((h, j) => { if (h) o[h] = row[j] !== undefined ? row[j] : ''; });
    out.push(o);
  }
  return out;
}

function rangos(res, esperados) {
  const vr = (res && res.valueRanges) || [];
  const map = {};
  esperados.forEach((name, k) => { map[name] = aObjetos((vr[k] || {}).values); });
  return map;
}

const resCat = $('00 · Leer catálogos').first().json;
const resUsr = $('00 · Leer usuarios').first().json;
const resTer = $('00 · Leer territorios').first().json;

if (!resCat || !resCat.valueRanges) {
  return [{ json: { success: false,
    message: 'No se pudo leer el libro de catálogos. ' +
      ((resCat && resCat.error && (resCat.error.message || resCat.error.status)) ||
       'Revisa que la credencial de Google tenga acceso al libro.') } }];
}

const hojas = rangos(resCat, TABS);
const usuarios = rangos(resUsr, ['USUARIOS-DATOMAESTRO'])['USUARIOS-DATOMAESTRO'];

/* ---------------------------------------------------------------------------
 * Normalización numérica.
 * Con UNFORMATTED_VALUE los números llegan como números, pero si alguien
 * escribe la tarifa como texto ("185.000") esto lo rescata. Vacío es null,
 * NO cero: un cero silencioso valorizaría mal un documento.
 * ------------------------------------------------------------------------ */
function num(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let t = String(v).trim().replace(/[$\s ]/g, '');
  if (!t) return null;
  const neg = /^-/.test(t);
  t = t.replace(/^-/, '');
  if (/^\d{1,3}(\.\d{3})+$/.test(t))      t = t.replace(/\./g, '');
  else if (/^\d{1,3}(,\d{3})+$/.test(t)) t = t.replace(/,/g, '');
  else if (/^\d+,\d{1,2}$/.test(t))      t = t.replace(',', '.');
  const n = Number(t);
  if (!isFinite(n)) return null;
  return neg ? -n : n;
}

const norm = (v) => String(v === undefined || v === null ? '' : v).trim();
const activa = (r) => norm(r.activo === undefined ? 'SI' : r.activo).toUpperCase() !== 'NO';

const NUMERICAS = { equipos: ['tarifa_diaria_clp', 'horas_min', 'seguro_uf_dia', 'alistamiento_clp'] };

const data = {};
for (const t of TABS) {
  const cols = NUMERICAS[t] || [];
  data[t] = (hojas[t] || []).filter(activa).map(r => {
    if (!cols.length) return r;
    const o = { ...r };
    for (const c of cols) o[c] = num(o[c]);
    return o;
  });
}

/* ---------------------------------------------------------------------------
 * TERRITORIOS · fuente real del selector de sucursal/territorio (libro de SAP,
 * hoja "Hoja 1"). Reemplaza a la hoja "sucursales" de catalogosalo para este uso.
 * Se descartan las entradas meta (ID negativo: "-Sin territorio-", raíz -1)
 * y las marcadas Inactivo.
 * ------------------------------------------------------------------------ */
const terRows = rangos(resTer, ['Hoja 1'])['Hoja 1'];
const territorios = (terRows || [])
  .filter(r => {
    const inactivo = norm(r['Inactivo']).toUpperCase();
    if (inactivo === 'S' || inactivo === 'SI' || inactivo === 'Y' || inactivo === 'YES') return false;
    const id = num(r['ID territorio']);
    return id !== null && id > 0;
  })
  .map(r => ({
    id: num(r['ID territorio']),
    descripcion: norm(r['Descripción']),
  }));
data.territorios = territorios;

/* ---------------------------------------------------------------------------
 * VENDEDORES · desde USUARIOS-DATOMAESTRO
 *
 * Es un maestro CORPORATIVO: mezcla ALOVENTAS, Argentina, Colombia, Logistic,
 * Panama, Paraguay, Peru y Rental. Tres trampas:
 *   1. EMPLEADO_VENTAS (SlpCode) es por base de SAP, no es único en la planilla:
 *      el código 36 existe en Argentina, Colombia y Perú a la vez.
 *   2. Hay correos repetidos entre empresas con códigos distintos.
 *   3. Muchas filas de VENDEDOR tienen EMPLEADO_VENTAS vacío.
 * Por eso: filtrar por EMPRESAPAIS, y si un correo sigue ambiguo, BLOQUEARLO.
 * ------------------------------------------------------------------------ */
const P = {};
(data.parametros || []).forEach(r => {
  if (!norm(r.clave)) return;
  const n = num(r.valor);
  P[norm(r.clave)] = (n !== null) ? n : r.valor;
});
data.parametrosMap = P;

const EMPRESAS = norm(P.empresas_validas || 'Rental')
  .split(',').map(x => x.trim().toUpperCase()).filter(Boolean);

function limpiaCorreo(v) {
  let m = norm(v).toLowerCase().replace(/[,;]+$/, '').replace(/\s+/g, '');
  m = m.replace('@alo_group.com', '@alo-group.com');
  return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(m) ? m : '';
}
const limpiaZona = (v) => norm(v).toUpperCase().replace(/^ZONA\s+/, '');

const descartes = { sinCorreo: 0, correoInvalido: 0, otraEmpresa: 0 };
const candidatos = [];
for (const r of usuarios) {
  const empresa = norm(r.EMPRESAPAIS).toUpperCase();
  if (EMPRESAS.length && !EMPRESAS.includes(empresa)) { descartes.otraEmpresa++; continue; }
  if (!norm(r.CORREO)) { descartes.sinCorreo++; continue; }
  const email = limpiaCorreo(r.CORREO);
  if (!email) { descartes.correoInvalido++; continue; }
  const n = num(r.EMPLEADO_VENTAS);
  candidatos.push({
    email: email, nombre: norm(r.NOMBRE_USUARIO),
    sales_person_code: (n !== null && n > 0) ? Math.round(n) : null,
    empleado_ventas: norm(r.EMPLEADO_VENTAS), codigo_usuario: norm(r.CODIGO_USUARIO),
    sucursal_raw: norm(r.SUCURSAL).toUpperCase(), zona: limpiaZona(r.ZONA),
    cargo: norm(r.NOMBRECARGO).toUpperCase(), telefono: norm(r.TELEFONO),
    empresa: empresa,
  });
}

const porCorreo = {};
for (const v of candidatos) (porCorreo[v.email] = porCorreo[v.email] || []).push(v);

const ambiguos = [], vendedores = [];
for (const email of Object.keys(porCorreo)) {
  const rs = porCorreo[email];
  const conCod = rs.filter(x => x.sales_person_code);
  const codigos = [...new Set(conCod.map(x => x.sales_person_code))];
  if (codigos.length > 1) {
    ambiguos.push({ email: email, codigos: codigos,
      detalle: conCod.map(x => x.empresa + '/' + x.sucursal_raw + '=' + x.sales_person_code) });
    vendedores.push({ ...rs[0], sales_person_code: null, ambiguo: true, codigos_en_conflicto: codigos });
    continue;
  }
  vendedores.push({ ...(conCod[0] || rs[0]), ambiguo: false });
}

// SUCURSAL del maestro -> código del catálogo, vía alias (se mantiene solo
// como referencia interna de vendedores; el selector ya usa data.territorios).
const sucRows = data.sucursales || [];
function resuelveSucursal(raw) {
  if (!raw) return '';
  const r = raw.toUpperCase().trim();
  for (const s of sucRows) {
    if (norm(s.codigo).toUpperCase() === r) return norm(s.codigo).toUpperCase();
    const alias = norm(s.alias).toUpperCase().split(',').map(x => x.trim()).filter(Boolean);
    if (alias.includes(r)) return norm(s.codigo).toUpperCase();
  }
  return '';
}
const sinMapear = new Set();
for (const v of vendedores) {
  v.sucursal = resuelveSucursal(v.sucursal_raw);
  if (v.sucursal_raw && !v.sucursal) sinMapear.add(v.sucursal_raw);
}
data.vendedores = vendedores;

/* ---------------- índices derivados que consume el front ---------------- */
const porRegion = {}, ciudades = {};
(data.comunas || []).forEach(r => {
  if (!r.region) return;
  (porRegion[r.region] = porRegion[r.region] || []).push(r.comuna);
  const c = r.ciudad || r.comuna;
  ciudades[r.region] = ciudades[r.region] || [];
  if (!ciudades[r.region].includes(c)) ciudades[r.region].push(c);
});
data.comunasPorRegion = porRegion;
data.ciudadesPorRegion = ciudades;

const porCat = {};
(data.equipos || []).forEach(e => {
  const cat = e.categoria || 'Otros';
  const code = norm(e.item_code);
  if (!code) return;
  porCat[cat] = porCat[cat] || [];
  if (!porCat[cat].some(x => x.item_code === code)) {
    porCat[cat].push({ item_code: code, nombre: e.nombre || code, tarifa: e.tarifa_diaria_clp });
  }
});
data.equiposPorCategoria = porCat;

/* ---------------------------- semáforo ---------------------------------- */
const sinTarifa = (data.equipos || [])
  .filter(e => !(Number(e.tarifa_diaria_clp) > 0)).map(e => e.item_code);
const sinCodigo = vendedores.filter(v => !v.sales_person_code && !v.ambiguo).map(v => v.email);

const avisos = [];
const vacias = TABS.filter(t => !(data[t] || []).length);
if (vacias.length) avisos.push('Hojas vacías o ilegibles: ' + vacias.join(', ') + '.');
if (!territorios.length) avisos.push(
  'El libro de Territorios no devolvió filas activas (revisa permisos y la hoja "Hoja 1").');
if (!vendedores.length) avisos.push(
  'Ningún usuario de USUARIOS-DATOMAESTRO para EMPRESAPAIS=' + EMPRESAS.join('/') + '.');
if (sinTarifa.length) avisos.push(
  sinTarifa.length + ' equipo(s) sin tarifa_diaria_clp: ' + sinTarifa.slice(0, 8).join(', ') +
  (sinTarifa.length > 8 ? '…' : '') + '. No se pueden cotizar.');
if (sinCodigo.length) avisos.push(
  sinCodigo.length + ' persona(s) sin EMPLEADO_VENTAS: no podrán cotizar.');
if (ambiguos.length) avisos.push(
  ambiguos.length + ' correo(s) con DOS códigos distintos (' +
  ambiguos.map(a => a.email).slice(0, 5).join(', ') + '): bloqueados hasta resolver.');
if (!norm(P.empresas_validas)) avisos.push(
  "Falta el parámetro 'empresas_validas' en la hoja parametros. Asumiendo Rental.");

return [{ json: {
  success: true,
  generado: new Date().toISOString(),
  conteo: { ...Object.fromEntries(TABS.map(t => [t, (data[t] || []).length])),
            territorios: territorios.length, vendedores: vendedores.length },
  avisos: avisos.length ? avisos : undefined,
  _vendedores: {
    filasLeidas: usuarios.length, empresasFiltradas: EMPRESAS, descartes: descartes,
    correosUnicos: vendedores.length,
    conCodigoValido: vendedores.filter(v => v.sales_person_code).length,
    sinCodigo: sinCodigo.slice(0, 30), ambiguos: ambiguos.slice(0, 20),
    sucursalesSinMapear: [...sinMapear],
  },
  data,
} }];

/** Extrae el mensaje de error de una respuesta del Service Layer. */
function sapError(res, fallback) {
  if (!res) return fallback;
  if (res.error) {
    const e = res.error;
    if (e.message && e.message.value) return e.message.value;
    if (typeof e.message === 'string') return e.message;
    if (typeof e === 'string') return e;
  }
  if (typeof res === 'string' && res.trim()) return res.slice(0, 300);
  return fallback;
}

/** Trae los catálogos desde /webhook/catalogos (Google Sheets). */
async function getCatalogos() {
  const r = await this.helpers.httpRequest({
    method: 'GET', url: 'https://alogroup.app.n8n.cloud/webhook/catalogos', json: true,
  });
  if (!r || !r.data) throw new Error('El webhook /catalogos no devolvió datos.');
  return r.data;
}

const SAP_BASE = 'https://sap.alo-group.com:50000/b1s/v1';

/** SELECT Price FROM ITM1 WHERE ItemCode=... AND PriceList=... (vía Service Layer). */
async function getItemPrice(ctx, itemCode, priceList, cookie) {
  const r = await ctx.helpers.httpRequest({
    method: 'GET',
    url: SAP_BASE + "/Items('" + itemCode + "')",
    qs: { '$select': 'ItemCode,ItemPrices' },
    headers: { Cookie: cookie },
    json: true,
    skipSslCertificateValidation: true,
  });
  const entry = (r.ItemPrices || []).find(p => String(p.PriceList) === String(priceList));
  return entry ? Number(entry.Price) || 0 : 0;
}

/** Datos de facturación del cliente: nombre, condición de pago, RUT y dirección
 * de facturación (bo_BillTo). Viene de BusinessPartners, no lo escribe el vendedor. */
async function getDatosFacturacion(ctx, cardCode, cookie) {
  const bp = await ctx.helpers.httpRequest({
    method: 'GET',
    url: SAP_BASE + "/BusinessPartners('" + cardCode + "')",
    qs: { '$select': 'CardCode,CardName,PayTermsGrpCode,FederalTaxID,BPAddresses' },
    headers: { Cookie: cookie },
    json: true,
    skipSslCertificateValidation: true,
  });
  const billTo = (bp.BPAddresses || []).find(a => a.AddressType === 'bo_BillTo') || null;
  let destFact = '', destFAddr = '';
  if (billTo) {
    destFact = billTo.AddressName || '';
    let countryName = billTo.Country || '';
    if (billTo.Country) {
      try {
        const pais = await ctx.helpers.httpRequest({
          method: 'GET', url: SAP_BASE + "/Countries('" + billTo.Country + "')",
          headers: { Cookie: cookie }, json: true, skipSslCertificateValidation: true,
        });
        countryName = pais.Name || billTo.Country;
      } catch (err) { /* se queda con el código de país si Countries falla */ }
    }
    destFAddr = [billTo.Street, billTo.City, countryName].filter(Boolean).join(' ');
  }
  const shipTos = (bp.BPAddresses || [])
    .filter(a => a.AddressType === 'bo_ShipTo' && a.Active !== 'tNO')
    .map(a => ({ name: a.AddressName || '', addr: [a.Street, a.City, a.Country].filter(Boolean).join(' '), faena: String(a.U_TipoFaena || '').trim() }));
  return {
    cardName: bp.CardName || '',
    condPago: bp.PayTermsGrpCode != null ? String(bp.PayTermsGrpCode) : '',
    rut: bp.FederalTaxID || '',
    destFact, destFAddr, shipTos,
  };
}

const norm = (v) => String(v === undefined || v === null ? '' : v)
  .trim().toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// ---------- Tramos de días -> PriceList de SAP (confirmados contra Formatted Search real) ----------
const ZONA_NORTE = new Set(['IQUIQUE', 'ANTOFAGASTA', 'COPIAPO']);
const TRAMOS_EQUIPO = [
  [1, 6, '6', '1'], [7, 14, '7', '2'], [15, 20, '8', '3'], [21, 29, '9', '4'], [30, Infinity, '10', '5'],
];
const TRAMOS_SEGURO = [
  [1, 6, '1'], [7, 13, '2'], [14, 20, '3'], [21, 29, '4'], [30, Infinity, '5'],
];
function priceListEquipo(dur, zonaNorte) {
  for (const [lo, hi, zn, base] of TRAMOS_EQUIPO) if (dur >= lo && dur <= hi) return zonaNorte ? zn : base;
  return null;
}
function priceListSeguro(dur) {
  for (const [lo, hi, l] of TRAMOS_SEGURO) if (dur >= lo && dur <= hi) return l;
  return null;
}

const body = $('01 · Webhook').first().json.body || {};
const ufRes = $('01 · Consultar tasa UF').first().json;
const sapCookie = 'B1SESSION=' + $('01 · Abrir sesión SAP').first().json.SessionId;

const cat = await getCatalogos.call(this);
const P   = cat.parametrosMap || {};

// ---------- entrada ----------
const cardCode        = body.cardCode || body.CardCode;
const vendedorEmail   = (body.vendedorEmail || body.userEmail || '').toLowerCase().trim();
const sucursalCod     = String(body.sucursal || body.Branch || '').trim();
const opprIdIn        = body.opprId || body.OpprId || null;

// Destino (dónde van las máquinas): texto libre -> U_Dest / U_DestAddr.
// (U_DestFact/U_DestFAddr son la dirección de FACTURACIÓN del cliente en SAP,
// se resuelven solas más abajo — no se tocan aquí.)
const destino    = body.destino || {};
const destLugar  = String(destino.lugar || body.destinoLugar || '').trim();

// Líneas de equipo: acepta el formato nuevo (array `lineas`) y, por
// compatibilidad, el formato viejo de un solo itemCode/durQty/descP.
let lineasIn = Array.isArray(body.lineas) ? body.lineas : null;
if (!lineasIn) {
  const legacyItem = body.itemCode || body.ItemCode;
  if (legacyItem) {
    lineasIn = [{
      itemCode: legacyItem,
      durQty: body.durQty !== undefined ? body.durQty : body.DurationQuantity,
      descP: body.descP !== undefined ? body.descP : body.DiscountPercent,
      incSeguro: body.incSeguro !== undefined ? body.incSeguro : true,
      incAlistamiento: body.incAlistamiento !== undefined ? body.incAlistamiento : true,
    }];
  } else {
    lineasIn = [];
  }
}

const stop = (msg) => [{ json: { success: false, _control: { continue: false, message: msg } } }];

// ---------- 1. validación de forma ----------
const e = [];
if (!cardCode)      e.push('falta el código de cliente');
if (!vendedorEmail) e.push('falta el correo del vendedor');
if (!sucursalCod)   e.push('falta la sucursal/territorio');
if (!destLugar)     e.push('falta el destino (dirección) de las máquinas');
if (!lineasIn.length) e.push('la cotización no tiene ningún equipo');

const DESCUENTO_MAX = 90; // tope duro de UI/negocio; independiente del parámetro de SAP.

const lineasParseadas = lineasIn.map((l, i) => {
  const n = i + 1;
  const itemCode = String(l.itemCode || l.ItemCode || '').trim();
  const rawDur = (l.durQty !== undefined && l.durQty !== null && l.durQty !== '')
               ? l.durQty : l.DurationQuantity;
  const durQty = (rawDur === undefined || rawDur === null || rawDur === '')
               ? NaN : parseInt(rawDur, 10);
  const descP = parseFloat(l.descP !== undefined ? l.descP : l.DiscountPercent) || 0;
  const incSeguro       = l.incSeguro !== undefined ? !!l.incSeguro : true;
  const incAlistamiento = l.incAlistamiento !== undefined ? !!l.incAlistamiento : true;

  if (!itemCode) e.push('línea ' + n + ': falta el código de equipo');
  if (!Number.isFinite(durQty)) e.push('línea ' + n + ': falta la cantidad de días de arriendo');
  else if (durQty < 3) e.push('línea ' + n + ': los días de arriendo deben ser 3 o más (mínimo 3, sin máximo)');
  if (descP < 0 || descP > DESCUENTO_MAX)
    e.push('línea ' + n + ': el descuento debe estar entre 0 y ' + DESCUENTO_MAX + '%');

  return { itemCode, durQty, descP, incSeguro, incAlistamiento };
});

if (e.length) return stop('Validación fallida: ' + e.join(', ') + '.');

// ---------- 2. vendedor: SIN código de SAP no se emite ----------
const vend = (cat.vendedores || []).find(v =>
  String(v.email || '').toLowerCase().trim() === vendedorEmail);
if (!vend) {
  return stop('El correo ' + vendedorEmail + ' no aparece en la columna CORREO de ' +
              'USUARIOS-DATOMAESTRO (libro USUARIOS-ALO). Agrégalo antes de cotizar.');
}
if (!vend.sales_person_code) {
  return stop('El vendedor ' + vendedorEmail + ' está en USUARIOS-DATOMAESTRO, pero su ' +
              'columna EMPLEADO_VENTAS no tiene un código numérico de SAP ' +
              '(valor actual: "' + (vend.empleado_ventas || '') + '"). ' +
              'Sin ese código la cotización quedaría a nombre de otra persona.');
}
const slpCode = parseInt(vend.sales_person_code, 10);

// ---------- 3. sucursal (13 validas SAP) y territorio ----------
const SUC_MAP = { 'IQUIQUE':'IQUIQUE','ANTOFAGASTA':'ANTOFAGA','COPIAPO':'COPIAPO','LA SERENA':'LASERENA','COQUIMBO':'COQUIMBO','SANTIAGO':'SANTIAGO','QUILPUE':'QUILPUE','RANCAGUA':'RANCAGUA','CURICO':'CURICO','CONCEPCION':'CONCEPCI','PUERTO MONTT':'PMONTT','VALPARAISO':'VALPARAI' };
const BRANCH = { 'IQUIQUE':'Iquique','ANTOFAGA':'Antofagasta','COPIAPO':'Copiapo','LASERENA':'La Serena','COQUIMBO':'Coquimbo','SANTIAGO':'Santiago','QUILPUE':'Quilpue','RANCAGUA':'Rancagua','CURICO':'Curico','CONCEPCI':'Concepcion','PMONTT':'Puerto Montt','VALPARAI':'Valparaiso' };
const sucUp = norm(sucursalCod);
const sucursalCode = BRANCH[sucUp] ? sucUp : (SUC_MAP[sucUp] || '--');
if (sucursalCode === '--') return stop('Sucursal invalida: "' + sucursalCod + '". Validas: ' + Object.keys(BRANCH).join(', ') + '.');
const branchName = BRANCH[sucursalCode];
const dim1 = sucursalCode;
const suc = (cat.territorios || []).find(t => String(t.id) === String(sucursalCod) || norm(t.descripcion) === norm(branchName) || norm(t.descripcion) === sucUp);
if (!suc) return stop('No se encontro el territorio SAP para la sucursal "' + branchName + '".');
const zonaNorte = ZONA_NORTE.has(sucUp);

// ---------- 4. tope de descuento, desde parámetros (puede ser más estricto) ----------
const topeDescParam = Number(P.descuento_max_pct);
const topeDesc = isFinite(topeDescParam) ? Math.min(topeDescParam, DESCUENTO_MAX) : DESCUENTO_MAX;
const excedidas = lineasParseadas.filter(l => l.descP > topeDesc);
if (excedidas.length) {
  return stop('El descuento supera el tope autorizado de ' + topeDesc +
              '% en el/los equipo(s): ' + excedidas.map(l => l.itemCode).join(', ') + '.');
}

// ---------- 5. UF: sin fallback inventado ----------
let ufRate = null;
if (ufRes && ufRes.data !== undefined && ufRes.data !== null) ufRate = Number(ufRes.data);
else if (ufRes && ufRes.value !== undefined && ufRes.value !== null) ufRate = Number(ufRes.value);
else if (ufRes && ufRes.Rate !== undefined) ufRate = Number(ufRes.Rate);

const necesitaUf = lineasParseadas.some(l => l.incSeguro);
if (necesitaUf && !(ufRate > 0)) {
  return stop('No se pudo obtener la tasa de la UF desde SAP. ' +
              'El seguro se calcula en UF, así que la cotización no se emite. ' +
              'Detalle: ' + sapError(ufRes, 'respuesta vacía de GetCurrencyRate') + '.');
}

// ---------- 5b. Datos de facturación del cliente (desde SAP, no del formulario) ----------
const fact = await getDatosFacturacion(this, cardCode, sapCookie);

// Direccion de despacho: debe ser una bo_ShipTo real del cliente CON Tipo de Faena (SAP lo exige).
const shipTosValidos = (fact.shipTos || []).filter(s => s.faena);
if (!shipTosValidos.length) return stop('El cliente ' + cardCode + ' no tiene direcciones de despacho (bo_ShipTo) con "Tipo de Faena" configurado en SAP.');
const destKey = norm(destLugar);
const ship = shipTosValidos.find(s => norm(s.name) === destKey);
if (!ship) return stop('El destino "' + destLugar + '" no es una direccion de despacho valida del cliente. Opciones con Tipo de Faena: ' + shipTosValidos.map(s => s.name).join(' | ') + '.');
const destName = ship.name;
const destAddr = ship.addr || destLugar;

// Vigencia de la cotización: hoy + días de validez configurados en parámetros.
const vence = new Date(Date.now() + (Number(P.dias_validez_oferta) || 30) * 86400000)
  .toISOString().slice(0, 10);

// ---------- 6. resolver precio real (Items/ItemPrices de SAP) y calcular ----------
const round = (n) => Math.round(n);
const horMinDefault = Number(P.horas_min_default) || 180;

const equipoLines = [];
const adicionales = [];
const detalleLineas = []; // para trazabilidad / registro en Sheets

let netoTotal = 0;

for (let i = 0; i < lineasParseadas.length; i++) {
  const l = lineasParseadas[i];
  const n = i + 1; // 1-based: es el U_LineaAsoc que espera VID_RTCOTADCollection

  const eqs = (cat.equipos || []).filter(x =>
    String(x.item_code || '').toUpperCase().trim() === l.itemCode.toUpperCase());
  if (!eqs.length) return stop('El equipo ' + l.itemCode + ' no está en la hoja "equipos" del catálogo.');
  const eq = eqs[0];
  const horMin = Number(eq.horas_min) || horMinDefault;

  const plEquipo = priceListEquipo(l.durQty, zonaNorte);
  if (!plEquipo) return stop('línea ' + n + ': no existe lista de precio para ' + l.durQty + ' días.');
  const precioBaseDiario = await getItemPrice(this, l.itemCode, plEquipo, sapCookie);
  if (!(precioBaseDiario > 0)) {
    return stop('El equipo ' + l.itemCode + ' no tiene precio cargado en SAP (Lista de precios ' + plEquipo + ').');
  }

  const valHr      = round(precioBaseDiario / (horMin / 30));
  const tarBase    = precioBaseDiario * l.durQty;
  const montoDesc  = round(tarBase * (l.descP / 100));
  const netoEquipo = tarBase - montoDesc;

  equipoLines.push({
    U_Linea: n,
    U_ItemCode: l.itemCode,
    U_ItemName: eq.nombre || l.itemCode,
    U_DurQty: l.durQty,
    U_DurPer: 'D',
    U_Cantidad: 1,
    U_Estado: 'A',
    U_HorMin: horMin,
    U_Moneda: P.moneda || 'CLP',
    U_TarBase: tarBase,
    U_ValHr: valHr, U_ValHrEx: valHr,
    U_DescP: l.descP, U_Desc: montoDesc,
    U_Neto: netoEquipo, U_NetoPQ: netoEquipo,
    U_Impuesto: 'IVA',
    U_Dim1: dim1, U_Dim2: 'ALQUILER', U_Dim3: 'VENTAS',
    U_Dest: destName, U_DestAddr: destAddr,
  });

  let netoAdicLinea = 0;
  let seguroClp = 0, alistaClp = 0;

  if (l.incSeguro) {
    const plSeguro = priceListSeguro(l.durQty);
    const precioUf = plSeguro ? await getItemPrice(this, 'SEG-' + l.itemCode, plSeguro, sapCookie) : 0;
    seguroClp = round(precioUf * ufRate * l.durQty);
    netoAdicLinea += seguroClp;
    adicionales.push({
      U_ItemCode: 'SEG-' + l.itemCode,
      U_ItemName: 'SEGURO ' + (eq.nombre || l.itemCode),
      U_Cantidad: 1,
      U_Dim1: dim1, U_Dim2: 'SEGUROAR', U_Dim3: 'VENTAS',
      U_Impuesto: 'IVA', U_WhsCode: 'ADMINVER',
      U_Precio: seguroClp, U_Neto: seguroClp, U_NetoPQ: seguroClp,
      U_LineaAsoc: n, U_CuotaAsoc: 1,
      U_Estado: 'A', U_DescP: 0, U_Desc: 0, U_Moneda: P.moneda || 'CLP',
    });
  }
  if (l.incAlistamiento) {
    alistaClp = round(await getItemPrice(this, 'zALI-' + l.itemCode, '1', sapCookie));
    netoAdicLinea += alistaClp;
    adicionales.push({
      U_ItemCode: 'zALI-' + l.itemCode,
      U_ItemName: 'ALISTAMIENTO ' + (eq.nombre || l.itemCode),
      U_Cantidad: 1,
      U_Dim1: dim1, U_Dim2: 'ALISTAAR', U_Dim3: 'VENTAS',
      U_Impuesto: 'IVA', U_WhsCode: 'ADMINVER',
      U_Precio: alistaClp, U_Neto: alistaClp, U_NetoPQ: alistaClp,
      U_LineaAsoc: n, U_CuotaAsoc: 1,
      U_Estado: 'A', U_DescP: 0, U_Desc: 0, U_Moneda: P.moneda || 'CLP',
    });
  }

  netoTotal += netoEquipo + netoAdicLinea;

  detalleLineas.push({
    itemCode: l.itemCode, itemNombre: eq.nombre || l.itemCode, categoria: eq.categoria || '',
    dias: l.durQty, descuentoPct: l.descP, descuentoMonto: montoDesc,
    precioBaseDiario, seguroClp, alistamientoClp: alistaClp, neto: netoEquipo + netoAdicLinea,
  });
}

const ivaPct    = Number(P.iva_pct);
const impuesto  = round(netoTotal * (isFinite(ivaPct) ? ivaPct : 0.19));
const totalDoc  = netoTotal + impuesto;
const hoy       = new Date().toISOString().slice(0, 10);

// ---------- 7. oportunidad ----------
const createOpp = !opprIdIn;
// DataOwnershipfield = OHEM.empID = columna CODIGO_USUARIO del maestro de usuarios.
// Territory = SapTerritoryID (id del catalogo de territorios). SAP (SP AG_TN_OOPR_OPV) los exige.
const ownerId = parseInt(vend.codigo_usuario, 10);
const territoryId = parseInt(suc.id, 10);
if (createOpp && !Number.isFinite(ownerId)) {
  return stop('El vendedor ' + vendedorEmail + ' no tiene CODIGO_USUARIO en USUARIOS-DATOMAESTRO. ' +
              'SAP lo exige como propietario (DataOwnershipfield) de la oportunidad.');
}
const opportunityPayload = createOpp ? {
  CardCode: cardCode,
  SalesPerson: slpCode,
  Source: 25,
  InterestLevel: 1,
  StartDate: hoy,
  PredictedClosingDate: vence,
  MaxLocalTotal: totalDoc,
  Remarks: 'Arriendo ' + cardCode + ' - ' + detalleLineas.map(d => d.itemCode).join('+') + '. Creada automáticamente desde el cotizador web.',
  Status: 'sos_Open',
  OpportunityName: ('ARRIENDO ' + cardCode + ' ' + detalleLineas.map(d => d.itemCode).join('+')).slice(0, 100),
  DataOwnershipfield: ownerId,
  Territory: territoryId,
  ClosingType: 'sos_Days',
  OpportunityType: 'boOpSales',
  U_TipoNegocio: 'ARRIENDO',
  U_G_User: vendedorEmail,
  SalesOpportunitiesLines: [{
    SalesPerson: slpCode, StartDate: hoy, ClosingDate: vence, StageKey: 2,
    PercentageRate: 1, MaxLocalTotal: totalDoc, Status: 'so_Open',
    DocumentType: 'bodt_MinusOne', U_TipoDocArriendo: '--',
  }],
} : null;

const quotePayload = {
  U_CardCode: cardCode,
  U_CardName: fact.cardName,
  U_Contacto: '',
  U_RefDate: hoy, U_DocDate: hoy, U_DueDate: vence,
  U_Vendedor: String(slpCode),
  U_OpprId: opprIdIn ? parseInt(opprIdIn, 10) : null,
  U_Estado: 'A',
  U_PerFact: P.periodo_facturacion_default || 'D',
  U_DiaFact: '',
  U_Moneda: P.moneda || 'CLP',
  U_DescP: 0, U_Desc: 0,
  U_Neto: netoTotal, U_Impuesto: impuesto,
  U_Total: totalDoc, U_TotalPQ: totalDoc,
  U_Sucursal: sucursalCode,
  U_Dest: destName,
  U_DestAddr: destAddr,
  U_DestFact: fact.destFact,
  U_DestFAddr: fact.destFAddr,
  U_CondPago: fact.condPago,
  U_Rut: fact.rut,
  U_APROB_COM: 'NO',
  U_APROB_FIN: 'NO',
  U_APROB_LOG: 'NO',
  U_TipoContrato: 'ARRIENDO',
  U_Comment: 'Creada automáticamente desde el cotizador web',
  VID_RTCOTDCollection: equipoLines,
  VID_RTCOTADCollection: adicionales,
};

return [{ json: {
  success: true, createOpp, opportunityPayload, quotePayload,
  _calculo: {
    zonaNorte, sucursal: suc.descripcion, slpCode, ufRate,
    netoTotal, impuesto, totalDoc,
    destino: { lugar: destLugar },
    lineas: detalleLineas,
    vendedorEmail, vendedorNombre: vend.nombre || '',
    cardCode,
  },
} }];

const oppRes = $input.first().json;
const prev = $('01 · ¿Crear oportunidad?').first().json;

const newId = oppRes && (oppRes.SequentialNo || oppRes.OpprId || oppRes.AbsoluteEntry);
if (!newId) {
  const det = (oppRes && oppRes.error && oppRes.error.message)
    ? (oppRes.error.message.value || oppRes.error.message)
    : 'respuesta inesperada del Service Layer';
  return [{ json: { success: false, _control: { continue: false,
    message: 'No se pudo crear la oportunidad en SAP: ' + det } } }];
}
const q = { ...prev.quotePayload, U_OpprId: parseInt(newId, 10) };
return [{ json: { ...prev, quotePayload: q, createdOpprId: newId } }];

/** Extrae el mensaje de error de una respuesta del Service Layer. */
function sapError(res, fallback) {
  if (!res) return fallback;
  if (res.error) {
    const e = res.error;
    if (e.message && e.message.value) return e.message.value;
    if (typeof e.message === 'string') return e.message;
    if (typeof e === 'string') return e;
  }
  if (typeof res === 'string' && res.trim()) return res.slice(0, 300);
  return fallback;
}

// Respuesta del POST VID_RTCOT (con neverError puede traer {error:...}).
const res = ($input.all()[0] && $input.all()[0].json) || {};

if (res && res.DocEntry) {
  // opprId y total salen del propio documento creado (confiable).
  return [{ json: { success: true, data: {
    docEntry: res.DocEntry,
    docNum: res.DocNum,
    opprId: res.U_OpprId != null ? res.U_OpprId : null,
    total: res.U_Total != null ? res.U_Total : null,
  } } }];
}
return [{ json: { success: false,
  message: sapError(res, 'SAP rechazÃ³ la cotizaciÃ³n sin devolver un motivo.') } }];

// Arma UNA fila con las columnas de la hoja 'Cotizaciones'.
// Se registra tanto el éxito como el rechazo: así queda la traza de intentos.
const r = $input.first().json;
const c = ($('01 · Validar y calcular').first().json || {})._calculo || {};
const d = r.data || {};
const lineas = c.lineas || [];

const f2 = (n) => (n === undefined || n === null || n === '') ? '' : n;
const join = (arr) => arr.join(' + ');

return [{ json: {
  fecha_hora:       new Date().toISOString().replace('T', ' ').slice(0, 19),
  doc_num:          f2(d.docNum),
  doc_entry:        f2(d.docEntry),
  oppr_id:          f2(d.opprId),
  card_code:        f2(c.cardCode),
  card_name:        f2($('01 · Webhook').first().json.body.cardName),
  item_code:        join(lineas.map(l => l.itemCode)),
  item_nombre:      join(lineas.map(l => l.itemNombre)),
  categoria:        join([...new Set(lineas.map(l => l.categoria))]),
  dias:             join(lineas.map(l => l.dias)),
  zona:             f2(c.zona),
  sucursal:         f2(c.sucursal),
  destino:          f2((c.destino || {}).completo),
  descuento_pct:    join(lineas.map(l => l.descuentoPct)),
  descuento_monto:  lineas.reduce((s, l) => s + (l.descuentoMonto || 0), 0),
  seguro_clp:       lineas.reduce((s, l) => s + (l.seguroClp || 0), 0),
  alistamiento_clp: lineas.reduce((s, l) => s + (l.alistamientoClp || 0), 0),
  neto:             f2(c.netoTotal),
  iva:              f2(c.impuesto),
  total:            f2(c.totalDoc),
  uf_usada:         f2(c.ufRate),
  vendedor_email:   f2(c.vendedorEmail),
  vendedor_nombre:  f2(c.vendedorNombre),
  slp_code:         f2(c.slpCode),
  estado:           r.success ? 'EMITIDA' : 'ERROR',
  origen:           'CRM web',
} }];

// El nodo de Sheets devuelve su propia salida; aquí se recupera la respuesta
// que espera el front, y se deja constancia de si el registro quedó grabado.
const r = $('01 · Validar respuesta SAP').first().json;
let registrado = true;
try {
  const g = $('01 · Registrar en Datos CRM').first().json;
  if (g && (g.error || g.__error)) registrado = false;
} catch (e) { registrado = false; }

if (r.success) {
  return [{ json: { ...r, data: { ...(r.data || {}), registradoEnPlanilla: registrado } } }];
}
return [{ json: r }];

const b = $('02 · Webhook').first().json.body || {};
const rut  = String(b.rut || '').replace(/[^0-9kK]/gi, '').toUpperCase();
const nom  = String(b.cardName || b.nombre || '').trim();
let   cc   = String(b.cardCode || '').trim();
// FederalTaxID en SAP se guarda CON guion (77082270-K), no pegado.
const rutDash = rut.length > 1 ? rut.slice(0, -1) + '-' + rut.slice(-1) : rut;
// Si no viene cardCode explicito pero si el RUT, se deriva (misma regla que
// Session.rutToCardCode en el front): 76.721.028-0 -> C76721028-0 (el CardCode
// de SAP lleva guion antes del digito verificador, NO va pegado).
if (!cc && rut && rut.length > 1) cc = 'C' + rutDash;
if (!rut && !nom && !cc) {
  return [{ json: { success: false, message: 'Indica un RUT, un CardCode o un nombre para buscar.' } }];
}
const q = (s) => String(s).replace(/'/g, "''");
// Con CardCode (derivado del RUT o explicito) y SIN nombre: acceso directo por
// clave, como pide el negocio -> GET BusinessPartners('C77389370-5').
// Es más rápido y confiable que un $filter, y evita falsos positivos por
// coincidencias parciales de contains().
if (cc && !nom) {
  return [{ json: { success: true, direct: true, query: "BusinessPartners('" + encodeURIComponent(cc) + "')" } }];
}
const conds = [];
if (cc)  conds.push("CardCode eq '" + q(cc) + "'");
if (rut) conds.push("contains(FederalTaxID,'" + q(rutDash) + "')");
if (nom) conds.push("contains(CardName,'" + q(nom) + "')");
// Sin restringir CardType: se incluyen tanto clientes (cCustomer) como leads
// (cLid), para no perder prospectos que aun no fueron convertidos en SAP.
const filter = "(" + conds.join(' or ') + ")";
// Sin $select para evitar propiedades invalidas; se piden todos los campos.
const qs = 'BusinessPartners?$filter=' + encodeURIComponent(filter) + '&$top=50';
return [{ json: { success: true, direct: false, query: qs } }];

function sapError(res, fallback){ if(!res)return fallback; if(res.error){const e=res.error; if(e.message&&e.message.value)return e.message.value; if(typeof e.message==='string')return e.message;} if(typeof res==='string'&&res.trim())return res.slice(0,300); return fallback; }
const res = $input.first().json;
const direct = !!$('02 · Armar consulta').first().json.direct;
// El acceso directo por clave (GET BusinessPartners('C...')) devuelve 404 con
// error de SAP cuando el CardCode no existe: eso NO es una falla, es 'sin resultados'.
if (direct && res && res.error) {
  return [{ json: { success: true, clientes: [], message: 'No existe un cliente con ese RUT/CardCode en SAP.' } }];
}
if (!res || res.error) return [{ json:{ success:false, message: sapError(res,'SAP no devolvió resultados.') } }];
const rows = direct ? (res.CardCode ? [res] : []) : (Array.isArray(res.value) ? res.value : (Array.isArray(res)?res:[]));
const list = rows.map(r => ({
  CardCode: r.CardCode,
  CardName: r.CardName,
  LicTradNum: r.FederalTaxID || '',
  PayTermsGrpName: r.PayTermsGrpCode != null ? String(r.PayTermsGrpCode) : '',
  U_EstadoTrib: r.Frozen === 'tYES' ? 'BLOQUEADO' : 'VIGENTE',
  Phone1: r.Phone1, EmailAddress: r.EmailAddress, City: r.City, Address: r.Address,
}));
return [{ json:{ success:true, clientes:list, message: list.length?undefined:'Sin resultados para esa búsqueda.' } }];

const b = $('03 · Webhook').first().json.body || {};

const texto  = String(b.texto || '').trim();
const estado = String(b.estado || '').trim();   // O | W | L
const etapa  = String(b.etapa || '').trim();
const q = (s) => String(s).replace(/'/g, "''");

const conds = [];
if (estado) {
  const m = { O: 'sos_Open', W: 'sos_Won', L: 'sos_Lost' };
  if (m[estado]) conds.push("Status eq '" + m[estado] + "'");
}
if (etapa) conds.push('SalesStage eq ' + parseInt(etapa, 10));
if (texto) {
  conds.push("contains(Remarks,'" + q(texto) + "')");
}
let qs = 'SalesOpportunities?$orderby=SequentialNo desc&$top=100';
if (conds.length) qs += '&$filter=' + encodeURIComponent(conds.join(' and '));
return [{ json: { success: true, query: qs } }];

/** Extrae el mensaje de error de una respuesta del Service Layer. */
function sapError(res, fallback) {
  if (!res) return fallback;
  if (res.error) {
    const e = res.error;
    if (e.message && e.message.value) return e.message.value;
    if (typeof e.message === 'string') return e.message;
    if (typeof e === 'string') return e;
  }
  if (typeof res === 'string' && res.trim()) return res.slice(0, 300);
  return fallback;
}

const res = $input.first().json;
if (!res || res.error) {
  return [{ json: { success: false,
    message: sapError(res, 'SAP no devolvió resultados para esta consulta.') } }];
}
const rows = Array.isArray(res.value) ? res.value : (Array.isArray(res) ? res : []);

const est = { sos_Open: 'O', sos_Won: 'W', sos_Lost: 'L' };
const list = rows.map(r => ({
  OpprId: r.SequentialNo, CardCode: r.CardCode, CardName: '', LicTradNum: '',
  Remarks: r.Remarks || r.Name || '',
  SalesPerson: r.SalesPerson,
  SalesStage: r.SalesStage != null ? String(r.SalesStage) : '1',
  MaxSumLoc: r.MaxLocalTotal || 0,
  PredDate: r.PredictedClosingDate || null,
  Status: est[r.Status] || 'O',
}));

// SalesOpportunities no trae CardName ni RUT: se completan con UNA consulta
// a BusinessPartners por los CardCode unicos de esta pagina de resultados,
// para que 'Cotizar' desde la oportunidad muestre el cliente real (antes
// quedaba '--' porque CardName nunca vino en la respuesta de SAP).
const codigos = [...new Set(list.map(o => o.CardCode).filter(Boolean))];
if (codigos.length) {
  const q = (s) => String(s).replace(/'/g, "''");
  const filtro = codigos.map(c => "CardCode eq '" + q(c) + "'").join(' or ');
  const cookie = 'B1SESSION=' + $('03 · Abrir sesión SAP').first().json.SessionId;
  try {
    const bp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://sap.alo-group.com:50000/b1s/v1/BusinessPartners',
      qs: { '$filter': filtro, '$select': 'CardCode,CardName,FederalTaxID', '$top': codigos.length },
      headers: { Cookie: cookie },
      json: true, skipSslCertificateValidation: true,
    });
    const porCodigo = {};
    (bp.value || []).forEach(b => { porCodigo[b.CardCode] = b; });
    list.forEach(o => {
      const b = porCodigo[o.CardCode];
      if (b) { o.CardName = b.CardName || ''; o.LicTradNum = b.FederalTaxID || ''; }
    });
  } catch (e) { /* si falla el enriquecimiento, se listan igual sin nombre/rut */ }
}

return [{ json: { success: true, oportunidades: list,
  message: list.length ? undefined : 'No hay oportunidades que coincidan con el filtro.' } }];

/** Trae los catálogos desde /webhook/catalogos (Google Sheets). */
async function getCatalogos() {
  const r = await this.helpers.httpRequest({
    method: 'GET', url: 'https://alogroup.app.n8n.cloud/webhook/catalogos', json: true,
  });
  if (!r || !r.data) throw new Error('El webhook /catalogos no devolvió datos.');
  return r.data;
}

const b = $('04 · Webhook').first().json.body || {};
const cat = await getCatalogos.call(this);
const P = cat.parametrosMap || {};
const stop = (m) => [{ json: { success: false, _control: { continue: false, message: m } } }];

/** email del vendedor -> SlpCode de SAP. Sin esto no se emite el documento. */
function slp(email) {
  const v = (cat.vendedores || []).find(x =>
    String(x.email || '').toLowerCase().trim() === String(email || '').toLowerCase().trim());
  return v && v.sales_person_code ? parseInt(v.sales_person_code, 10) : null;
}
/** Mensaje preciso según por qué no se pudo resolver el vendedor. */
function errVendedor(email) {
  const v = (cat.vendedores || []).find(x =>
    String(x.email || '').toLowerCase().trim() === String(email || '').toLowerCase().trim());
  if (!v) return 'El correo ' + email + ' no aparece en la columna CORREO de ' +
                 'USUARIOS-DATOMAESTRO (libro USUARIOS-ALO).';
  return 'El vendedor ' + email + ' no tiene un código numérico en la columna ' +
         'EMPLEADO_VENTAS de USUARIOS-DATOMAESTRO.';
}

const cardCode = String(b.cardCode || '').trim();
const nombre   = String(b.nombre || '').trim();
const email    = b.vendedorEmail || b.userEmail;

if (!cardCode) return stop('Falta el código de cliente.');
if (!nombre)   return stop('Falta el nombre de la oportunidad.');

const code = slp(email);
if (!code) return stop(errVendedor(email));

const etapa = parseInt(b.salesStage || 1, 10);
const pctPorEtapa = { 1: 5, 3: 20, 4: 50, 5: 90 };
const potencial = Math.round(Number(b.potencial) || 0);
const hoy = new Date().toISOString().slice(0, 10);

// La fecha llega en ISO desde el front (app.js ya la convierte).
let cierre = b.fechaCierre || null;
if (cierre && !/^\d{4}-\d{2}-\d{2}$/.test(cierre)) cierre = null;

const payload = {
  CardCode: cardCode,
  SalesPerson: code,
  StartDate: hoy,
  PredictedClosingDate: cierre,
  MaxLocalTotal: potencial,
  SalesStage: etapa,
  Status: 'sos_Open',
  OpportunityType: 'boOpSales',
  Remarks: (nombre + (b.comentarios ? ' — ' + String(b.comentarios) : '')).slice(0, 250),
  U_TipoNegocio: 'ARRIENDO',
  SalesOpportunitiesLines: [{
    SalesPerson: code, StartDate: hoy, StageKey: etapa,
